                                <span class="material-symbols-outlined text-primary text-4xl mb-2 block" style="font-variation-settings: 'FILL' 1;">shield_with_heart</span>
                                <span class="font-label-sm text-[10px] tracking-widest text-on-surface-variant uppercase">Encrypted</span>
                            </div>
                            <!-- Decorative Orbit -->
