                                <div class="absolute top-0 left-1/2 -translate-x-1/2 w-1.5 h-1.5 bg-primary rounded-full shadow-[0_0_10px_rgba(242,202,80,0.8)]"></div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
        <!-- Support Form Section -->
        <section class="w-full px-margin-mobile lg:px-margin-desktop pb-section-gap">
            <div class="max-w-container-max mx-auto grid grid-cols-1 lg:grid-cols-12 gap-gutter">
                <!-- Subtle Sidebar Info -->
                <div class="lg:col-span-3 order-2 lg:order-1 flex flex-col gap-12 mt-12 lg:mt-0">

                    <div class="p-8 bg-surface-container-low rounded-xl border-l-2 border-primary/30">
                        <p class="font-label-sm text-label-sm text-primary mb-2 uppercase">Priority Response</p>
                        <p class="font-body-md text-on-surface-variant leading-relaxed">
                            Black Tier members receive a guaranteed response within 15 minutes, 24/7.
                        </p>
                    </div>
                </div>
                <!-- Main Form Card -->
                <div class="lg:col-span-8 lg:col-start-5 order-1 lg:order-2">
                    <div id="supportFormContainer" class="relative group"><div class="absolute -inset-0.5 bg-gradient-to-tr from-primary/10 to-transparent opacity-30 blur-xl"></div><div class="relative bg-surface-container-lowest p-8 lg:p-16 border border-outline-variant/10 shadow-2xl min-h-[400px] flex items-center justify-center"><form id="supportForm" class="w-full"><div class="grid grid-cols-1 md:grid-cols-2 gap-10 mb-12"><div class="relative"><input required="" class="peer w-full bg-transparent border-b border-outline-variant/30 py-4 text-on-surface focus:outline-none focus:border-primary transition-colors font-body-lg" id="name" placeholder=" " type="text"><label class="absolute left-0 top-4 text-on-surface-variant/60 font-label-sm uppercase tracking-widest transition-all peer-focus:-top-4 peer-focus:text-[10px] peer-focus:text-primary peer-[:not(:placeholder-shown)]:-top-4 peer-[:not(:placeholder-shown)]:text-[10px]" for="name">Full Name</label></div><div class="relative"><input required="" class="peer w-full bg-transparent border-b border-outline-variant/30 py-4 text-on-surface focus:outline-none focus:border-primary transition-colors font-body-lg" id="email" placeholder=" " type="email"><label class="absolute left-0 top-4 text-on-surface-variant/60 font-label-sm uppercase tracking-widest transition-all peer-focus:-top-4 peer-focus:text-[10px] peer-focus:text-primary peer-[:not(:placeholder-shown)]:-top-4 peer-[:not(:placeholder-shown)]:text-[10px]" for="email">Secure Email</label></div></div><div class="mb-12"><label class="block font-label-sm text-[10px] text-primary uppercase tracking-[0.2em] mb-4">Inquiry Nature</label><div class="relative"><select class="w-full bg-surface-container-low border border-outline-variant/20 px-6 py-4 appearance-none text-on-surface focus:outline-none focus:border-primary/50 transition-all font-body-md rounded-none" id="inquiryType"><option value="general">General Inquiry</option><option value="report">Report a Member</option><option value="technical">Technical Support</option><option value="membership">Membership Services</option></select><div class="absolute right-6 top-1/2 -translate-y-1/2 pointer-events-none"><span class="material-symbols-outlined text-primary">expand_more</span></div></div></div><div class="relative mb-16"><textarea required="" class="peer w-full bg-transparent border-b border-outline-variant/30 py-4 text-on-surface focus:outline-none focus:border-primary transition-colors font-body-lg resize-none" id="message" placeholder=" " rows="5"></textarea><label class="absolute left-0 top-4 text-on-surface-variant/60 font-label-sm uppercase tracking-widest transition-all peer-focus:-top-4 peer-focus:text-[10px] peer-focus:text-primary peer-[:not(:placeholder-shown)]:-top-4 peer-[:not(:placeholder-shown)]:text-[10px]" for="message">Detailed Request</label></div><div class="flex flex-col md:flex-row items-center justify-between gap-8"><div class="flex items-center gap-3"><div class="w-2 h-2 bg-primary rounded-full animate-pulse shadow-[0_0_8px_rgba(242,202,80,1)]"></div><span class="font-label-sm text-[11px] text-on-surface-variant/70 uppercase tracking-widest">Discretion Guaranteed</span></div><button class="group relative px-12 py-5 overflow-hidden transition-all duration-500 hover:shadow-[0_0_30px_rgba(242,202,80,0.2)]" type="submit"><div class="absolute inset-0 bg-primary translate-y-[101%] group-hover:translate-y-0 transition-transform duration-500 ease-out"></div><div class="absolute inset-0 border border-primary"></div><span class="relative font-label-sm text-label-sm text-primary group-hover:text-on-primary transition-colors duration-500 tracking-[0.2em] uppercase">Send Message</span></button></div></form><div id="successMessage" class="hidden text-center max-w-md animate-pulse"><span class="material-symbols-outlined text-primary text-5xl mb-6 block">verified_user</span><h3 class="font-display-lg text-headline-md text-primary mb-4 uppercase tracking-widest">Message Transmitted</h3><p class="font-body-lg text-on-surface-variant leading-relaxed">Your message has been received. Our concierge team will contact you shortly.</p></div></div><script>document.getElementById('supportForm').addEventListener('submit', function(e) { e.preventDefault(); const form = this; const success = document.getElementById('successMessage'); form.classList.add('hidden'); success.classList.remove('hidden'); });</script></div>
                </div>
            </div>
        </section>
        <!-- Visual Asset Section -->
        <section class="w-full h-[60vh] relative overflow-hidden">
            <div class="absolute inset-0 z-10 bg-gradient-to-b from-background via-transparent to-background"></div>
            <div class="absolute inset-0 bg-fixed bg-cover bg-center grayscale contrast-125 brightness-50" data-alt="Ultra-luxurious minimalist architectural detail of a private vault or high-end lounge. Dark matte surfaces, sharp geometric shadows, and a single thin line of golden light cutting across the frame. High-end editorial photography style, mysterious and exclusive." style="background-image: url('https://lh3.googleusercontent.com/aida-public/AB6AXuAKHOTwl3N8ih0W_9fXfNjgvFkP7ytt9--rjTVnzqxNOjvsL5pJHAvallHeqNNxlyKeqMldNowlUhRiw-P3X-6GI4LSkA5MepONdIXausuXXedlva_-mbbGVknO4NKf8zwc7pYTI_KjCG-6qiE2Crst-UR7td4Nls9haHtqKrwOIp-HxGQ68JOfEJuYWFYVz3itNNaWfZMX5wHb4n16vS1WKrCrDwhDHpONMSMazTa18ZdyRCN2T6mUscJqAep6shL91sA4sMcD21o')"></div>
            <!-- Floating Stats / Micro-infographic -->
            <div class="relative z-20 h-full flex items-center justify-center">
                <div class="flex flex-wrap justify-center gap-16 lg:gap-32">
                    <div class="text-center">
                        <div class="font-display-lg text-primary text-5xl mb-2 counter" data-target="99.9">99.9%</div>
                        <p class="font-label-sm text-on-surface-variant/60 uppercase tracking-widest">Privacy Rating</p>
                    </div>
                    <div class="text-center">
                        <div class="font-display-lg text-primary text-5xl mb-2 counter" data-target="24">24</div>
                        <p class="font-label-sm text-on-surface-variant/60 uppercase tracking-widest">Global Hubs</p>
                    </div>
                    <div class="text-center">
                        <div class="font-display-lg text-primary text-5xl mb-2 counter" data-target="15">15</div>
                        <p class="font-label-sm text-on-surface-variant/60 uppercase tracking-widest">Min Response</p>
                    </div>
                </div>
            </div>
        </section>
        <script>
            // Micro-interactions and Counter Animation
            document.addEventListener('DOMContentLoaded', () => {
                // Counter Animation
                const counters = document.querySelectorAll('.counter');
                const observerOptions = {
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            const target = +entry.target.getAttribute('data-target');
                            const count = 0;
                            const speed = 50;

                            const updateCount = () => {
                                const current = +entry.target.innerText;
                                const increment = target / speed;

                                if (current < target) {
                                    entry.target.innerText = Math.ceil(current + increment);
                                    setTimeout(updateCount, 20);
                                } else {
                                    entry.target.innerText = target + (entry.target.getAttribute('data-target').includes('.') ? '%' : '');
                                }
                            };
                            updateCount();
                            observer.unobserve(entry.target);
                        }
                    });
                }, observerOptions);

                counters.forEach(counter => observer.observe(counter));

                // Form Submission Feedback
                const form = document.getElementById('supportForm');
                form.addEventListener('submit', (e) => {
                    e.preventDefault();
                    const btn = form.querySelector('button');
                    const originalText = btn.querySelector('span').innerText;

                    btn.disabled = true;
                    btn.querySelector('span').innerText = 'SECURELY SENDING...';

                    setTimeout(() => {
                        btn.querySelector('span').innerText = 'MESSAGE TRANSMITTED';
                        btn.classList.add('bg-primary/20');
                        setTimeout(() => {
                            btn.disabled = false;
                            btn.querySelector('span').innerText = originalText;
                            btn.classList.remove('bg-primary/20');
                            form.reset();
                        }, 3000);
                    }, 1500);
                });
            });
        </script>
    </div></main><footer class="w-full bg-surface-container-lowest py-section-gap border-t border-outline-variant/10"><div class="max-w-container-max mx-auto px-margin-mobile lg:px-margin-desktop"><div class="flex flex-col md:flex-row justify-between items-center gap-unit"><div class="flex items-center gap-4 opacity-70"><img alt="Blinglink" class="h-6 w-auto grayscale brightness-200" src="https://lh3.googleusercontent.com/aida/AP1WRLvFx9epfW5F0ifQUgFkzC8oaW_8wRR9BPI9YcoRDx_NtaVCl6h4EUj8uQ0N0-CUKXHpyXxE4UZR7eMK5XEgNV0Y0JpO2DxLCAysgJb_3Au-G26dWr7wbrFFPNZBV2LDCDsykoaj6AIuZm4AXdOyG0wgDTzKDFd60da0F7RnoF3FP1EMKugf-S_lgE_NEaeQEyjVzQCNfZm9VIIK3F8OCZbUIT06In5-j-IMF8WMpmOkBe6hs0K38zi1m94"/></div><p class="font-label-sm text-label-sm text-on-surface-variant tracking-widest uppercase">© 2026 Blinglink. Exquisite Connection.</p></div></div></footer>

